    private function settleAllocationOrMark($markerId,$allocationId,$paymentId,$userId){try{(new CustomerFundsService($this->db,$this->entity))->settleWithSupplierPayment($allocationId,$paymentId,$userId);}catch(Throwable$e){$this->db->query("UPDATE ".MAIN_DB_PREFIX."cpo_supplier_action SET status='correction_required',error_code='ALLOCATION_LINK_FAILED',fk_user_modif=".(int)$userId." WHERE entity=".$this->entity." AND rowid=".(int)$markerId);throw new RuntimeException('Supplier payment exists, but customer funds allocation needs correction. No payment was recreated.');}}
    private function assertAllocationSelectable($id,array$operation,$currency,$amount){$row=$this->one("SELECT rowid,amount,currency_code FROM ".MAIN_DB_PREFIX."cpcc_fund_allocation WHERE entity=".$this->entity." AND rowid=".(int)$id." AND status='reserved' AND target_type='operation' AND target_id=".(int)$operation['rowid']." AND fk_operation=".(int)$operation['rowid']." AND fk_soc=".(int)$operation['fk_soc']." AND fk_project=".(int)$operation['fk_project']);if(!$row)throw new RuntimeException('Choose a reserved customer funds allocation for this exact operation and project (allocation '.(int)$id.', operation '.(int)$operation['rowid'].', customer '.(int)$operation['fk_soc'].', project '.(int)$operation['fk_project'].').');if(strtoupper((string)$row->currency_code)!==strtoupper($currency))throw new RuntimeException('Customer funds allocation must use the supplier payment currency.');if((float)$row->amount>$amount+0.00001)throw new RuntimeException('Customer funds allocation cannot exceed the supplier payment amount.');}
    private function availableAllocations(array$operation,$currency){$rows=array();$res=$this->db->query("SELECT rowid,amount,currency_code,request_key FROM ".MAIN_DB_PREFIX."cpcc_fund_allocation WHERE entity=".$this->entity." AND status='reserved' AND target_type='operation' AND target_id=".(int)$operation['rowid']." AND fk_operation=".(int)$operation['rowid']." AND fk_soc=".(int)$operation['fk_soc']." AND fk_project=".(int)$operation['fk_project']." AND currency_code='".$this->db->escape($currency)."' ORDER BY rowid");while($res&&($row=$this->db->fetch_object($res)))$rows[]=(array)$row;return$rows;}

    private function requiredOperation($id){$row=$this->one("SELECT rowid,ref,service_type,fk_soc,fk_project,fk_commande FROM ".MAIN_DB_PREFIX."cpo_operation WHERE entity=".$this->entity." AND rowid=".(int)$id." AND status=1");if(!$row||(int)$row->fk_soc<=0||(int)$row->fk_project<=0||(int)$row->fk_commande<=0)throw new RuntimeException('An active operation with customer, project and sales order is required.');return(array)$row;}
    private function requiredCustomerOrder(array$operation){$order=new Commande($this->db);if($order->fetch((int)$operation['fk_commande'])<=0||(int)$order->entity!==$this->entity||(int)$order->socid!==(int)$operation['fk_soc']||(int)$order->fk_project!==(int)$operation['fk_project'])throw new RuntimeException('Customer sales order context mismatch.');return$order;}
    private function requiredSupplier($id){$supplier=new Societe($this->db);if($id<=0||$supplier->fetch($id)<=0||(int)$supplier->entity!==$this->entity||empty($supplier->fournisseur)||empty($supplier->status))throw new RuntimeException('Select an active native supplier.');return$supplier;}
    private function supplierOrder($id,array$operation,$supplierId){$order=new CommandeFournisseur($this->db);if($order->fetch($id)<=0||(int)$order->entity!==$this->entity||(int)$order->socid!==$supplierId||(int)$order->fk_project!==(int)$operation['fk_project'])throw new RuntimeException('Supplier order context mismatch.');return$order;}
    private function supplierInvoice($id,array$operation,$supplierId,$order){$invoice=new FactureFournisseur($this->db);if($invoice->fetch($id)<=0||(int)$invoice->entity!==$this->entity||(int)$invoice->socid!==$supplierId||(int)$invoice->fk_project!==(int)$operation['fk_project']||(int)$invoice->type!==FactureFournisseur::TYPE_STANDARD)throw new RuntimeException('Supplier invoice context mismatch.');$link=$this->one("SELECT rowid FROM ".MAIN_DB_PREFIX."element_element WHERE sourcetype='order_supplier' AND targettype='invoice_supplier' AND fk_source=".(int)$order->id." AND fk_target=".(int)$invoice->id);if(!$link)throw new RuntimeException('Supplier invoice is not linked to the supplier order.');return$invoice;}
    private function requiredMarker($operationId,$type,$lock=false){$row=$this->one("SELECT * FROM ".MAIN_DB_PREFIX."cpo_supplier_action WHERE entity=".$this->entity." AND fk_operation=".(int)$operationId." AND action_type='".$this->db->escape($type)."' ORDER BY rowid DESC LIMIT 1".($lock?' FOR UPDATE':''));if(!$row)throw new RuntimeException('Required supplier workflow evidence is missing.');return$row;}
    private function suppliers(){$rows=array();$res=$this->db->query("SELECT rowid,nom,name_alias FROM ".MAIN_DB_PREFIX."societe WHERE entity=".$this->entity." AND fournisseur=1 AND status=1 ORDER BY nom");while($res&&($row=$this->db->fetch_object($res)))$rows[]=(array)$row;return$rows;}
    private function purchaseLines($customerOrder,$raw,array$currency){$source=array();foreach((array)$customerOrder->lines as$line)$source[(int)$line->id]=$line;$out=array();foreach((array)$raw as$item){$lineId=(int)($item['customer_line_id']??0);$cost=is_numeric($item['unit_cost']??null)?(float)$item['unit_cost']:-1;$vat=is_numeric($item['vat']??null)?(float)$item['vat']:-1;if($lineId<=0&&$cost<0)continue;if(!isset($source[$lineId])||$cost<0||$cost>1000000000||$vat<0||$vat>100)throw new RuntimeException('Each purchase line needs the original order line, explicit unit cost, and VAT.');$line=$source[$lineId];if((float)$line->qty<=0)throw new RuntimeException('Purchase quantity must be positive.');$out[]=array('source_id'=>$lineId,'product_id'=>(int)$line->fk_product,'product_type'=>(int)$line->product_type,'unit_id'=>$line->fk_unit,'qty'=>(float)$line->qty,'cost'=>$cost,'base_cost'=>$cost/$currency['tx'],'vat'=>$vat,'description'=>$this->clean($line->desc?:'Purchase for '.$customerOrder->ref,1000),'supplier_ref'=>$this->clean($item['supplier_ref']??'',64));}return$out;}
    private function verifySupplierOrder($order,array$operation,$supplierId,array$currency,array$lines){
        if((int)$order->socid!==$supplierId)throw new RuntimeException('Created supplier order supplier differs from approved input.');
        if((int)$order->fk_project!==(int)$operation['fk_project'])throw new RuntimeException('Created supplier order project differs from the operation.');
        $actualCurrency=$this->objectCurrency($order);
        if($actualCurrency['code']!==$currency['code']||abs($actualCurrency['tx']-$currency['tx'])>0.0000001)throw new RuntimeException('Created supplier order currency differs from approved input (actual '.$actualCurrency['code'].' @ '.$actualCurrency['tx'].', expected '.$currency['code'].' @ '.$currency['tx'].').');
        if(count((array)$order->lines)!==count($lines))throw new RuntimeException('Created supplier order line count differs from approved input.');
    }
    private function verifySupplierInvoice($invoice,array$operation,$supplierId,$order,array$currency){if((int)$invoice->socid!==$supplierId||(int)$invoice->fk_project!==(int)$operation['fk_project']||$this->objectCurrency($invoice)['code']!==$currency['code']||count((array)$invoice->lines)!==count((array)$order->lines))throw new RuntimeException('Created supplier invoice context, currency, or lines differ from supplier order.');foreach((array)$order->lines as$i=>$source){$target=$invoice->lines[$i]??null;if(!$target||abs((float)$target->qty-(float)$source->qty)>0.000001||abs((float)$target->tva_tx-(float)$source->tva_tx)>0.000001||abs((float)$target->multicurrency_subprice-(float)$source->multicurrency_subprice)>0.000001)throw new RuntimeException('Supplier invoice lines, VAT, or original-currency costs differ from supplier order.');}}
    private function invoiceSummary($id){$row=$this->one($this->invoiceSummarySql($id));if(!$row)return null;$total=(float)$row->total_amount;$paid=(float)$row->paid_amount;return array('total'=>$total,'paid'=>$paid,'remaining'=>max(0,$total-$paid),'currency'=>(string)$row->currency,'status'=>(int)$row->fk_statut);}
    private function invoiceSummarySql($id){$base=$this->db->escape(strtoupper((string)getDolCurrency()));return"SELECT f.fk_statut,UPPER(CASE WHEN TRIM(COALESCE(f.multicurrency_code,''))<>'' THEN f.multicurrency_code ELSE '".$base."' END) currency,CASE WHEN TRIM(COALESCE(f.multicurrency_code,''))<>'' THEN f.multicurrency_total_ttc ELSE f.total_ttc END total_amount,COALESCE((SELECT SUM(CASE WHEN TRIM(COALESCE(f.multicurrency_code,''))<>'' THEN pf.multicurrency_amount ELSE pf.amount END) FROM ".MAIN_DB_PREFIX."paiementfourn_facturefourn pf WHERE pf.fk_facturefourn=f.rowid),0) paid_amount FROM ".MAIN_DB_PREFIX."facture_fourn f WHERE f.entity=".$this->entity." AND f.rowid=".(int)$id;}
    private function currency($code,$tx){$base=strtoupper((string)getDolCurrency());$code=strtoupper(trim((string)$code));if(!preg_match('/^[A-Z]{3}$/',$code))throw new RuntimeException('Choose a valid supplier currency.');$tx=is_numeric($tx)?(float)$tx:0;if($code===$base)$tx=1.0;if($tx<=0)throw new RuntimeException('Enter the approved exchange rate explicitly. No automatic FX is allowed.');return array('code'=>$code,'tx'=>$tx,'base'=>$base);}
    private function objectCurrency($object){$base=strtoupper((string)getDolCurrency());$code=strtoupper(trim((string)$object->multicurrency_code));if($code==='')$code=$base;$tx=$code===$base?1.0:(float)$object->multicurrency_tx;if($tx<=0)throw new RuntimeException('Native supplier currency evidence is invalid.');return array('code'=>$code,'tx'=>$tx,'base'=>$base);}
    private function bankAccounts($currency){$rows=array();$base=$this->db->escape(strtoupper((string)getDolCurrency()));$res=$this->db->query("SELECT rowid,label,bank,UPPER(CASE WHEN TRIM(COALESCE(currency_code,''))<>'' THEN currency_code ELSE '".$base."' END) currency FROM ".MAIN_DB_PREFIX."bank_account WHERE entity=".$this->entity." AND clos=0 ORDER BY label");while($res&&($row=$this->db->fetch_object($res)))if((string)$row->currency===$currency)$rows[]=(array)$row;return$rows;}
    private function bankAccount($id,$currency){$base=$this->db->escape(strtoupper((string)getDolCurrency()));$row=$this->one("SELECT rowid,UPPER(CASE WHEN TRIM(COALESCE(currency_code,''))<>'' THEN currency_code ELSE '".$base."' END) currency FROM ".MAIN_DB_PREFIX."bank_account WHERE entity=".$this->entity." AND rowid=".(int)$id." AND clos=0");if(!$row||(string)$row->currency!==$currency)throw new RuntimeException('Supplier payment bank must use the same currency.');return$row;}
    private function paymentModes(){$rows=array();$res=$this->db->query("SELECT id,code,libelle FROM ".MAIN_DB_PREFIX."c_paiement WHERE active=1 AND code<>'INTR' ORDER BY sortorder,code");while($res&&($row=$this->db->fetch_object($res)))$rows[]=(array)$row;return$rows;}
    private function paymentMode($code){$row=$this->one("SELECT id,code FROM ".MAIN_DB_PREFIX."c_paiement WHERE active=1 AND code='".$this->db->escape($code)."' AND code<>'INTR'");if(!$row)throw new RuntimeException('Choose an active supplier payment method.');return$row;}
    public static function canReadSupplierWorkflow($user){return self::isInternal($user)&&(!empty($user->admin)||(self::right($user,'fournisseur','commande','lire')&&self::right($user,'fournisseur','facture','lire')));}
    public static function canCreateSupplierOrder($user){return self::isInternal($user)&&(!empty($user->admin)||self::rightEither($user,array(array('fournisseur','commande','creer'),array('supplier_order','creer'))));}
    public static function canValidateSupplierOrder($user){if(!self::isInternal($user)||!empty($user->admin))return self::isInternal($user);return getDolGlobalString('MAIN_USE_ADVANCED_PERMS')?self::right($user,'fournisseur','supplier_order_advance','validate'):self::canCreateSupplierOrder($user);}
    public static function canCreateSupplierInvoice($user){return self::isInternal($user)&&(!empty($user->admin)||self::rightEither($user,array(array('fournisseur','facture','creer'),array('supplier_invoice','creer'))));}
    public static function canValidateSupplierInvoice($user){if(!self::isInternal($user)||!empty($user->admin))return self::isInternal($user);return getDolGlobalString('MAIN_USE_ADVANCED_PERMS')?self::right($user,'fournisseur','supplier_invoice_advance','validate'):self::canCreateSupplierInvoice($user);}
    /** Match Dolibarr 23 supplier payment creation: supplier-invoice create plus bank read. */
    public static function canPostSupplierPayment($user){return self::isInternal($user)&&(!empty($user->admin)||(self::canCreateSupplierInvoice($user)&&self::right($user,'banque','lire')));}
    private static function isInternal($user){return !empty($user)&&!empty($user->id)&&empty($user->socid);}
    private static function rightEither($user,array$paths){foreach($paths as$path)if(call_user_func_array(array(__CLASS__,'right'),array_merge(array($user),$path)))return true;return false;}
    private static function right($user){$path=array_slice(func_get_args(),1);return !empty($user)&&method_exists($user,'hasRight')&&(bool)call_user_func_array(array($user,'hasRight'),$path);}
    private function assertStaff($user){if(!self::isInternal($user))throw new RuntimeException('Staff access required.');if(empty($user->admin)&&!$user->hasRight('chinaplanetoperations','operation_write'))throw new RuntimeException('Operation write permission is required.');}
    private function assertOrderCreatePermission($user){$this->assertStaff($user);if(!self::canCreateSupplierOrder($user))throw new RuntimeException('Native supplier-order create permission is required.');}
    private function assertOrderValidatePermission($user){$this->assertStaff($user);if(!self::canValidateSupplierOrder($user))throw new RuntimeException('Native supplier-order validation permission is required.');}
    private function assertInvoiceCreatePermission($user){$this->assertStaff($user);if(!self::canCreateSupplierInvoice($user))throw new RuntimeException('Native supplier-invoice create permission is required.');}
    private function assertInvoiceValidatePermission($user){$this->assertStaff($user);if(!self::canValidateSupplierInvoice($user))throw new RuntimeException('Native supplier-invoice validation permission is required.');}
    private function assertPaymentPermission($user){$this->assertStaff($user);if(!self::canPostSupplierPayment($user))throw new RuntimeException('Native supplier-invoice create and bank-read permissions are required to record a supplier payment.');}
    private function token($kind,$key){$key=trim((string)$key);if(!preg_match('/^[a-f0-9]{40}$/i',$key))throw new RuntimeException('Invalid guided action token. Reload and try again.');return'CPO-'.$kind.'-'.strtoupper($key);}
    private function lineHash(array$lines){return array_map(function($l){return array($l['source_id'],$l['product_id'],$l['qty'],$l['cost'],$l['vat'],$l['supplier_ref']);},$lines);}
    private function date($value){$value=trim((string)$value);return preg_match('/^\d{4}-\d{2}-\d{2}$/',$value)?$value:'';}
    private function clean($value,$max){return mb_substr(trim(strip_tags((string)$value)),0,$max);}
    private function orderStatus($order){return isset($order->status)?(int)$order->status:(int)$order->statut;}
    private function supplierOrderStatus($order){return isset($order->status)?(int)$order->status:(int)$order->statut;}
    private function nullableInt($v){return(int)$v>0?(string)(int)$v:'NULL';}
    private function num($v){return number_format((float)$v,12,'.','');}
    private function one($sql){$res=$this->db->query($sql);if(!$res)throw new RuntimeException($this->db->lasterror());return$this->db->fetch_object($res)?:null;}
    private function log($operationId,$action,$message,$userId){if(!$this->db->query("INSERT INTO ".MAIN_DB_PREFIX."cpo_activity(entity,fk_operation,fk_task,action_code,message,visibility,fk_user,date_action) VALUES(".$this->entity.",".(int)$operationId.",NULL,'".$this->db->escape($action)."','".$this->db->escape($message)."','internal',".(int)$userId.",NOW())"))throw new RuntimeException($this->db->lasterror());}
    private function lock($name){$row=$this->one("SELECT GET_LOCK('".$this->db->escape($name)."',5) acquired");if(!$row||(int)$row->acquired!==1)throw new RuntimeException('Supplier workflow is busy. Try again.');return$name;}
    private function unlock($name){if($name!=='')$this->db->query("SELECT RELEASE_LOCK('".$this->db->escape($name)."')");}
    private function markCorrection($token,$userId){$this->db->query("UPDATE ".MAIN_DB_PREFIX."cpo_supplier_action SET status='correction_required',error_code='EVIDENCE_MISMATCH',fk_user_modif=".(int)$userId." WHERE entity=".$this->entity." AND request_token='".$this->db->escape($token)."' AND status<>'confirmed'");}
